def choose_move(observation):
    w = int(observation.get("grid_width") or 8)
    h = int(observation.get("grid_height") or 8)
    sp = observation.get("self_position") or (0, 0)
    op = observation.get("opponent_position") or (0, 0)
    sx, sy = int(sp[0]), int(sp[1])
    ox, oy = int(op[0]), int(op[1])

    obstacles = observation.get("obstacles") or []
    blocked = set()
    for p in obstacles:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            bx, by = int(p[0]), int(p[1])
            if 0 <= bx < w and 0 <= by < h:
                blocked.add((bx, by))

    resources = []
    for p in observation.get("resources") or []:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            rx, ry = int(p[0]), int(p[1])
            if 0 <= rx < w and 0 <= ry < h and (rx, ry) not in blocked:
                resources.append((rx, ry))
    if not resources:
        return [0, 0]

    def cheb(ax, ay, bx, by):
        dx = ax - bx
        if dx < 0:
            dx = -dx
        dy = ay - by
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    def step_towards(tx, ty, x, y):
        dx = tx - x
        if dx > 0:
            mdx = 1
        elif dx < 0:
            mdx = -1
        else:
            mdx = 0
        dy = ty - y
        if dy > 0:
            mdy = 1
        elif dy < 0:
            mdy = -1
        else:
            mdy = 0
        nx, ny = x + mdx, y + mdy
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in blocked:
            return mdx, mdy
        return None

    best = None
    best_key = None
    # Prefer resources where we will be closer than opponent (positive advantage),
    # then closer to us, then deterministic position tiebreak.
    for rx, ry in resources:
        self_d = cheb(sx, sy, rx, ry)
        opp_d = cheb(ox, oy, rx, ry)
        advantage = opp_d - self_d  # >0 means we are closer
        closer_penalty = 0 if advantage > 0 else (abs(advantage) + 8)
        # Also bias away from being too slow in total
        key = (closer_penalty, -advantage, self_d, (rx + ry), rx, ry)
        if best_key is None or key < best_key:
            best_key = key
            best = (rx, ry)

    tx, ty = best
    move = step_towards(tx, ty, sx, sy)
    if move is not None:
        return [int(move[0]), int(move[1])]

    # If blocked on straight approach, pick best among all neighbor moves.
    candidates = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = sx + dx, sy + dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in blocked:
                self_d = cheb(nx, ny, tx, ty)
                opp_d = cheb(ox, oy, tx, ty)
                advantage = opp_d - self_d
                closer_penalty = 0 if advantage > 0 else (abs(advantage) + 8)
                # deterministic tiebreak by dx,dy
                candidates.append((closer_penalty, -advantage, self_d, dx, dy))
    if not candidates:
        return [0, 0]
    candidates.sort()
    return [int(candidates[0][3]), int(candidates[0][4])]

